def transform(grid):
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Retain the two solid colored rectangular regions; discard isolated noise.
    out=[[bg for _ in row] for row in grid]
    # connected components of non-background; retain components with multiple cells
    h,w=len(grid),len(grid[0]); seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]==bg or (r,c) in seen: continue
        col=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
              seen.add((yy,xx)); stack.append((yy,xx))
        if len(comp)>1:
          for y,x in comp: out[y][x]=col
    return out
